import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FiUser, FiPhone, FiLock } from 'react-icons/fi';

const Login = () => {
    const [identifier, setIdentifier] = useState('');
    const [password, setPassword] = useState('');
    const [loginType, setLoginType] = useState('phone');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        if (!identifier || !password) { setError('Preencha todos os campos'); return; }
        setLoading(true);
        const result = await login(identifier, password);
        if (result.success) navigate(result.user.type === 'vendedor' ? '/seller/dashboard' : '/');
        else setError('Usuário ou senha incorretos');
        setLoading(false);
    };

    return (
        <div className="max-w-md mx-auto">
            <div className="bg-white rounded-xl shadow-md p-8">
                <h2 className="text-2xl font-bold text-center mb-6">Entrar</h2>
                {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4">{error}</div>}
                
                <div className="flex gap-2 mb-6">
                    <button onClick={() => setLoginType('phone')} className={`flex-1 py-2 rounded-lg border ${loginType === 'phone' ? 'bg-primary-600 text-white' : 'border-gray-300'}`}>
                        <FiPhone className="inline mr-2" /> Telefone
                    </button>
                    <button onClick={() => setLoginType('name')} className={`flex-1 py-2 rounded-lg border ${loginType === 'name' ? 'bg-primary-600 text-white' : 'border-gray-300'}`}>
                        <FiUser className="inline mr-2" /> Nome
                    </button>
                </div>
                
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">{loginType === 'phone' ? 'Telefone' : 'Nome'}</label>
                        <div className="relative">
                            {loginType === 'phone' ? <FiPhone className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" /> : <FiUser className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />}
                            <input type={loginType === 'phone' ? 'tel' : 'text'} value={identifier} onChange={e => setIdentifier(e.target.value)} placeholder={loginType === 'phone' ? "923456789" : "Seu nome"} className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <div className="mb-6">
                        <label className="block text-gray-700 mb-2">Senha</label>
                        <div className="relative">
                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                            <input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Sua senha" className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <button type="submit" disabled={loading} className="w-full bg-primary-600 text-white py-2 rounded-lg hover:bg-primary-700">{loading ? 'Entrando...' : 'Entrar'}</button>
                </form>
                <p className="text-center mt-4">Não tem conta? <Link to="/register" className="text-primary-600">Cadastre-se</Link></p>
            </div>
        </div>
    );
};

export default Login;
